        exists 1%Z, 1%Z, 1%Z, c, cdc, dtc, adc, (CMAPV adc (c_d cv) (c_nalloc cv) (c_n cv) 0). exact X.
      - destruct (copy_opix C A' A3 m3 r6 w' h' 1 0 cv HOK' Hw' Hh'
                    (or_intror (ex_intro _ pixd (ex_intro _ cd (ex_intro _ data (conj E10' PT)))))) as (c & cdc & dtc & adc & X).
        exists w', h', 1%Z, c, cdc, dtc, adc, (CMAPV adc (c_d cv) (c_nalloc cv) (c_n cv) 0). exact X. }
    destruct CO as (w2 & h2 & d2 & c & cdc & dtc & adc & cv2 & Rc10 & Hc & OPc & OUTc & FRc).
    assert (SVm : SAVED3 MM s ret regs) by (apply (saved_keep _ _ _ _ _ SV5 ltac:(lia) ltac:(lia)); intros a Ha; apply OUTMM; lia).
