    assert (R48m : rdn SEGS m3 (Z_to_bv 64 (s - 48)) 8 = Some (Z_to_le_bytes 8 pix)).
    { rewrite (FRM_rdn16 C (s - 64) MM m3 (s - 48) 8 CK F3) by (rewrite ?Etop, ?LV; cbn; lia). rewrite <- R48.
      apply rdn_ext; change (Z.of_nat 8) with 8%Z; rewrite u_Z2bv by lia; [lia|]. intros x Hx. apply OUTMM. lia. }
    assert (OPs3 : opix C A3 m3 pix w h d cm dat (c_arr cv) cv).
    { apply (opix_live C A').
      - apply (opix_livk _ _ MM); [| exact L3 | rewrite ?Evm; lia].
        apply (opix_frame _ _ M5); [exact OP5 |]. intros x Hx. apply OUTMM. rewrite ?Evm in Hx. lia.
      - intros q k Bq Lq. destruct (oblk_dec c dtc cdc adc q) as [Bc|NBc].
        + exfalso. rewrite (proj1 (FRc q Bc)) in Lq. discriminate.
        + rewrite (OUTc q NBc). exact Lq. }
    assert (SOK3 : store_ok SEGS m3 (Z_to_bv 64 (s - 64)) 64 = true) by (apply (W_sok_win C A3 m3 _ (s - 64) 64 CK HW3); rewrite ?Etop, ?LV; cbn; lia).
    assert (Y6 : getr r6 2 = Z_to_bv 64 (s - 64)) by (csr; reflexivity).
    apply (rz_reach _ _ _ _ S (w_pure _ _ _ _ HW3) (fz_C al_rom (mkFP fr2 cs2) r6 m3 s c ltac:(lia) Hc SOK3 Y6 Rc10)).
    intros fin (r7 & M7 & -> & RI7 & R56 & X1 & X2 & X10 & AG7).
    assert (HW7 : W C A3 M7 (with_vmmaps vm3 md)) by (apply (W_rinv_win C A3 m3 M7 _ (s - 56) 8 CK HW3 RI7); rewrite Etop, ?LV; lia).
    assert (OUT7 : forall x : word, (u x < alloc_top (c_vm C))%Z -> M7 x = m3 x).
    { intros x Hx. apply (rinv_out1 _ _ _ _ x RI7). rewrite ?Evm in Hx. lia. }
    pose proof (opix_frame _ _ _ _ _ _ _ _ _ _ _ _ OPs3 OUT7) as OPs7.
    pose proof (opix_frame _ _ _ _ _ _ _ _ _ _ _ _ OPc OUT7) as OPc7.
    assert (SV7 : SAVED3 M7 s ret regs) by (apply (saved_keep _ _ _ _ _ SV6 ltac:(lia) ltac:(lia)); intros a Ha; apply (rinv_out1 _ _ _ _ a RI7); lia).
    assert (R48' : rdn SEGS M7 (Z_to_bv 64 (s - 48)) 8 = Some (Z_to_le_bytes 8 pix)).
    { rewrite <- R48m. apply rdn_ext; change (Z.of_nat 8) with 8%Z; rewrite u_Z2bv by lia; [lia|]. intros x Hx. apply (rinv_out1 _ _ _ _ x RI7). lia. }
    assert (T7 : getr r7 4 = Z_to_bv 64 1195296) by (csr; reflexivity).
    replace (Z_to_bv 64 445244) with (445244 : word) by (apply bv_eq; reflexivity).
    apply (pixDestroy_opix_W (mkFP fr2 cs2) C A3 M7 (with_vmmaps vm3 md) r7 (s - 64) (s - 48) pix w h d cm dat (c_arr cv) cv (Z_to_bv 64 405544) S
             CK HW7 X2 ltac:(rewrite <- Zminus_mod_idemp_l, Hsp16; reflexivity) ltac:(rewrite Etop; unfold ALLOC_STACK; rewrite LV; lia) ltac:(rewrite Etop; lia)
             X1 ltac:(red; apply bv_eq; reflexivity) T7 X10 ltac:(lia) ltac:(rewrite Etop; lia) R48' OPs7).
    intros A5 m5 vm5 r8 HW5' CS5 DEAD5 KEEP5 PM5 RD5 FR5 RT5. rewrite ?with_vmmaps_twice in HW5' |- *.
    pose proof PM5 as [F5 L5].
    assert (SV8 : SAVED3 m5 s ret regs) by (sv_frm SV7 F5 Etop Evm).
    assert (APART : forall q, oblk pix dat cm (c_arr cv) q -> ~ oblk c dtc cdc adc q)
      by exact (oblk_apart _ _ _ _ _ _ _ _ _ _ _ _ OP0 (fun q Bc => proj1 (FRc q Bc))).
    assert (OPc5 : opix C A5 m5 c w2 h2 d2 cdc dtc adc cv2).
    { apply (opix_livk _ _ M7); [| exact L5 | rewrite ?Evm; lia].
      apply (opix_live_out C A3 A5 M7 c w2 h2 d2 cdc dtc adc cv2 (oblk pix dat cm (c_arr cv)) OPc7 KEEP5).
      intros q Bc Bp. exact (APART q Bp Bc). }
    assert (Yr8 : getr r8 2 = Z_to_bv 64 (s - 64)) by (csr; reflexivity).
    apply (rz_reach _ _ _ _ S (w_pure _ _ _ _ HW5') (fz_D al_rom (mkFP fr2 cs2) r8 m5 s ltac:(lia) Yr8)).
    intros fin (r9 & M9 & -> & EM9 & D1 & D2 & D10 & AG9). subst M9.
    assert (R56' : rdn SEGS m5 (Z_to_bv 64 (s - 56)) 8 = Some (Z_to_le_bytes 8 c)).
    { rewrite <- R56. apply rdn_ext; change (Z.of_nat 8) with 8%Z; rewrite u_Z2bv by lia; [lia|]. intros x Hx. apply FR5. lia. }
    assert (T9 : getr r9 4 = Z_to_bv 64 1195296) by (csr; reflexivity).
    replace (Z_to_bv 64 445244) with (445244 : word) by (apply bv_eq; reflexivity).
    apply (pixDestroy_opix_W (mkFP fr2 cs2) C A5 m5 (with_vmmaps vm5 md) r9 (s - 64) (s - 56) c w2 h2 d2 cdc dtc adc cv2 (Z_to_bv 64 405552) S
             CK HW5' D2 ltac:(rewrite <- Zminus_mod_idemp_l, Hsp16; reflexivity) ltac:(rewrite Etop; unfold ALLOC_STACK; rewrite LV; lia) ltac:(rewrite Etop; lia)
             D1 ltac:(red; apply bv_eq; reflexivity) T9 D10 ltac:(lia) ltac:(rewrite Etop; lia) R56' OPc5).
    intros A6 m6 vm6 r10 HW6 CS6 DEAD6 KEEP6 PM6 RD6 FR6 RT6. rewrite ?with_vmmaps_twice in HW6 |- *.
