    apply (rz_reach _ _ _ _ S (w_pure _ _ _ _ HW6) (fz_Z al_rom (mkFP fr2 cs2) r10 m6 s ret ret (getr regs 8) (getr regs 9) ltac:(lia) Hret eq_refl Z8 Z16 Z24 Y10)).
    intros fin (r11 & M11 & -> & EM11 & U2 & U10 & U8 & U9 & AG11). subst M11.
