    destruct (aroom_nonneg _ _ _ _ Hrm3) as [K0 B0].
    pose proof (RT5 _ _ Hrm3 K0 B0) as Hrm5. rewrite !Z.sub_0_r in Hrm5.
    pose proof (RT6 _ _ Hrm5 K0 B0) as Hrm6. rewrite !Z.sub_0_r in Hrm6.
    assert (LQf : forall q, live A6 q = live A q).
    { intros q.
